#!/usr/bin/env python3
"""RSNA dense v4 cache, full build (optionally one shard of the study list) -- Kaggle CPU script generated by scripts/make_kaggle_kernel.py.

Preprocessing only: no training, labels or submission. Builds every training
study in train_series.csv with the D1 policy (3 fluid slots, 12 windows over
5-95 % of each series, 224 px, NPZ) using parallel decoding, then validates the
complete manifest (every shard hash, mask and shape) before reporting success.
Missing planes are masked; undecodable studies are quarantined and reported.
"""
from __future__ import annotations

import base64
import hashlib
import importlib
import importlib.metadata
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile
import tempfile
import time
from pathlib import Path

SOURCE_B64 = ""  # filled by the generator
SOURCE_SHA256 = ""  # filled by the generator
BUILD_INFO = {}  # filled by the generator

POLICY = {"slots": "PILOT_SLOTS", "n_centers": 12, "center_lower": 0.05, "center_upper": 0.95, "size": 224}  # define
SHARD = {"index": 0, "count": 1}  # define
MAX_CACHE_BYTES = 18 * 1024**3
CODEC_PINS = {"pydicom": "3.0.1", "pylibjpeg": "2.1.0", "pylibjpeg-libjpeg": "2.4.0", "pylibjpeg-openjpeg": "2.6.0"}
WORK = Path(os.environ.get("RSNA_WORK_DIR", "/kaggle/working"))
SMOKE = os.environ.get("RSNA_LOCAL_SMOKE") == "1"


def atomic_json(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, allow_nan=False), encoding="utf-8")
    tmp.replace(path)


def version(name):
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return None


def setup_packages() -> dict:
    target = Path(tempfile.gettempdir()) / "rsna-runtime-deps"
    pins = {"pydicom": CODEC_PINS["pydicom"]} if SMOKE else CODEC_PINS
    needed = [f"{n}=={v}" for n, v in pins.items() if version(n) != v]
    if needed:
        target.mkdir(exist_ok=True)
        subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--quiet",
                        "--no-deps", "--upgrade", "--target", str(target), *needed], check=True)
    sys.path.insert(0, str(target))
    # Worker processes must import the same pinned codecs.
    os.environ["PYTHONPATH"] = os.pathsep.join(filter(None, [str(target), os.environ.get("PYTHONPATH")]))
    importlib.invalidate_caches()
    import numpy as np
    import PIL
    import pydicom
    if pydicom.__version__ != CODEC_PINS["pydicom"]:
        raise RuntimeError("pydicom imported at an unexpected version; restart the session")
    if not SMOKE:
        for module in ("pylibjpeg", "libjpeg", "openjpeg"):
            importlib.import_module(module)
    return {"python": sys.version, "numpy": np.__version__, "Pillow": PIL.__version__,
            **{n: version(n) for n in CODEC_PINS}}


def unpack_source() -> Path:
    data = base64.b64decode(SOURCE_B64, validate=True)
    if hashlib.sha256(data).hexdigest() != SOURCE_SHA256:
        raise RuntimeError("Embedded source integrity failure")
    root = Path(tempfile.gettempdir()) / ("rsna-src-" + SOURCE_SHA256[:16])
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
        for member in archive.getmembers():
            rel = Path(member.name)
            if not member.isfile() or rel.is_absolute() or ".." in rel.parts:
                raise RuntimeError("Invalid embedded archive member")
            out = root / rel
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_bytes(archive.extractfile(member).read())
    sys.path.insert(0, str(root / "src"))
    os.environ["PYTHONPATH"] = os.pathsep.join(filter(None, [str(root / "src"), os.environ.get("PYTHONPATH")]))
    return root


def discover_root() -> Path:
    explicit = os.environ.get("RSNA_INPUT_ROOT")
    for candidate in ([Path(explicit)] if explicit else []) + [Path("/kaggle/input/rsna-knee-abnormality-detection"),
                                                               Path("/kaggle/input/competitions/rsna-knee-abnormality-detection")]:
        if (candidate / "train_series.csv").is_file() and (candidate / "train_series").is_dir():
            return candidate
    raise RuntimeError("Competition data not mounted")


def main() -> None:
    started = time.time()
    packages = setup_packages()
    unpack_source()
    from rsna_knee.data import cache_build
    from rsna_knee.hashing import sha256_file
    root = discover_root()
    dest = WORK / "cache"
    WORK.mkdir(parents=True, exist_ok=True)
    free = shutil.disk_usage(WORK).free
    if free < MAX_CACHE_BYTES + 512 * 1024**2:
        raise RuntimeError(f"Insufficient free disk for bounded cache: {free}")
    workers = max(1, min(4, os.cpu_count() or 1))
    import csv
    with (root / "train_series.csv").open(newline="") as handle:
        all_uids = sorted({row["StudyInstanceUID"] for row in csv.DictReader(handle)})
    study_ids = all_uids[SHARD["index"]::SHARD["count"]]
    result = {"status": "running", "policy": POLICY, "shard": SHARD, "n_shard_studies": len(study_ids),
              "shard_uids_sha256": hashlib.sha256("\n".join(study_ids).encode()).hexdigest(), "workers": workers, "source_sha256": SOURCE_SHA256,
              "build_info": BUILD_INFO, "packages": packages, "cpu_count": os.cpu_count()}
    atomic_json(WORK / "campaign-result.json", result)
    try:
        manifest = cache_build.build_cache(
            series_csv=root / "train_series.csv", dicom_root=root / "train_series", dest=dest,
            study_ids=study_ids, crop_mm=POLICY.get("crop_mm", 160.0), intensity=POLICY.get("intensity", "slice"),
            size=POLICY["size"], n_centers=POLICY["n_centers"], center_lower=POLICY["center_lower"],
            center_upper=POLICY["center_upper"], slots=getattr(cache_build, POLICY["slots"]), strict_series=True,
            resume=True, max_cache_bytes=MAX_CACHE_BYTES, workers=workers, progress_every=100, index_flush_every=100)
    except Exception as error:
        result.update(status="failed", error=f"{error.__class__.__name__}: {str(error)[:500]}",
                      wall_seconds=round(time.time() - started, 1))
        atomic_json(WORK / "campaign-result.json", result)
        raise
    build_seconds = time.time() - started
    t0 = time.time()
    ready, reason = cache_build.manifest_ready(dest / "manifest.json")
    shape = [len(manifest["preprocess_config"]["slots"]), POLICY["n_centers"], 3, POLICY["size"], POLICY["size"]]
    # manifest_ready stops at an incomplete scope; verify every built shard either way.
    bad = {uid: why for uid, meta in manifest["studies"].items()
           if (why := cache_build._check_shard(dest / f"{uid}.npz", meta, expected_shape=shape,
                                               pp_hash=manifest["preprocess_hash"]))}
    status = "ok" if ready else ("partial" if reason == "requested_scope_incomplete" and not bad else "invalid")
    result.update(
        status=status, bad_shards=bad, all_built_shards_verified=not bad,
        manifest_ready=[ready, reason], verify_seconds=round(time.time() - t0, 1),
        manifest_sha256=sha256_file(dest / "manifest.json"), preprocess_hash=manifest["preprocess_hash"],
        n_studies=manifest["n_studies"], n_requested=manifest["n_requested"], n_quarantine=manifest["n_quarantine"],
        quarantine=manifest["quarantine"], requested_complete=manifest["requested_complete"],
        compressed_byte_total=manifest["compressed_byte_total"], coverage=manifest["coverage"],
        build_seconds=round(build_seconds, 1), wall_seconds=round(time.time() - started, 1),
        note="Full manifest verification re-hashes every shard; quarantined studies are listed, never zero-filled.")
    atomic_json(WORK / "campaign-result.json", result)
    print(json.dumps({k: result[k] for k in ("status", "manifest_ready", "n_studies", "n_quarantine",
                                             "compressed_byte_total", "build_seconds")}), flush=True)


if __name__ == "__main__":
    main()
